[Form]
public class MetContainerTablelListPage extends FormRun
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    
}

/// <summary>
/// Form initialise method
/// </summary>
public void init()
{
    if (element.args().callerName() == menuItemDisplayStr(METSalesOrderFinalizationWorkbench))
    {
        metSalesOrderShipmentLoadHeader = element.args().record();
    }
    super();
}

            /// <summary>
            /// Filtered lookup in case called from Finalisation screen
            /// </summary>
            /// <param name = "_formControl">FormControl reference</param>
            /// <param name = "_filterStr">Filter string</param>
            public void lookup(FormControl _formControl, str _filterStr)
            {
                if (metSalesOrderShipmentLoadHeader.RecId)
                {
                    Query                   query = new Query();
                    QueryBuildDataSource    queryBuildDataSource;
                    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(MetContainerTypeTable), _formControl);
                    
                    sysTableLookup.addLookupField(fieldNum(MetContainerTypeTable, ContainerTypeCode));
                    
                    queryBuildDataSource = query.addDataSource(tableNum(MetContainerTypeTable));
                    queryBuildDataSource.addRange(fieldNum(MetContainerTypeTable, InventLocationId)).value(queryValue(metSalesOrderShipmentLoadHeader.Warehouse));

                    sysTableLookup.parmQuery(query);
                    sysTableLookup.performFormLookup();
                }
                else
                {
                    super(_formControl, _filterStr);
                }
            }

            /// <summary>
            /// Datasource validate field method
            /// </summary>
            /// <returns>Boolean value</returns>
            public boolean validate()
            {
                boolean ret;
            
                ret = super();
            
                if (metSalesOrderShipmentLoadHeader.RecId)
                {
                    METContainerTypeTable       metContainerTypeTable;

                    select firstonly RecId from metContainerTypeTable
                        where metContainerTypeTable.ContainerTypeCode == MetContainerTable.ContainerTypeCode    &&
                            metContainerTypeTable.InventLocationId == metSalesOrderShipmentLoadHeader.Warehouse;

                    if (metContainerTypeTable.RecId == 0)
                    {
                        ret = checkFailed(strFmt("@MET:InvalidContainer", MetContainerTable.ContainerTypeCode));
                    }
                }
                return ret;
            }
